using System; using System.Collections.Generic; using System.Linq; using System.IO; using System.Web.Script.Serialization; using AFramePlugin;
class ReviewProbe {
 static JavaScriptSerializer J=new JavaScriptSerializer();
 static void Main(string[] args) {
 var sample=FrameSolutionSelection.FromDict(J.DeserializeObject(File.ReadAllText(args[0])));
 var result=new List<object>();
 foreach(var x in new[]{100d,150d,151d,169.999d,170d}) {
  var s=sample.Clone();s.geometry.insulation_layers_mm=new List<double>{150};s.geometry.cladding_front_offset_mm=230;
  var i=FrameNodeGeometryInput.CreateDefault();i.profile_near_face_x_mm=x;
  var r=FrameNodeGeometry.Evaluate(s,i);
  result.Add(new { name="unknown_surface_profile_at_"+x, r.CanInsert,r.Status,r.ClearanceStatus,r.GapText,issues=r.Issues.Select(p=>p.Code).ToArray(),r.Missing });
 }
 foreach(var x in new[]{1e-28,1e-29}) {
  var s=sample.Clone();s.geometry.insulation_layers_mm=new List<double>();s.geometry.cladding_front_offset_mm=null;
  var i=FrameNodeGeometryInput.CreateDefault();i.profile_near_face_x_mm=x;
  try { var r=FrameNodeGeometry.Evaluate(s,i);result.Add(new{name="small_"+x,status=r.Status}); }catch(FrameNodeGeometryException e){result.Add(new{name="small_"+x,code=e.Code,message=e.Message});}
 }
 Console.WriteLine(J.Serialize(result));
 }
}
